90. public class AbstractIdleServiceTest extends TestCase {
91. 
92.   // Functional tests using real thread. We only verify publicly visible state.
93.   // Interaction assertions are done by the single-threaded unit tests.
94.   public static class FunctionalTest extends TestCase {
95. 
96.     private static class DefaultService extends AbstractIdleService {
97.       @Override
98.       protected void startUp() throws Exception {}
99. 
100.       @Override
101.       protected void shutDown() throws Exception {}
102.     }
103. 
104.     public void testServiceStartStop() throws Exception {
105.       AbstractIdleService service = new DefaultService();
106.       service.startAsync().awaitRunning();
107.       assertEquals(Service.State.RUNNING, service.state());
108.       service.stopAsync().awaitTerminated();
109.       assertEquals(Service.State.TERMINATED, service.state());
110.     }
111. 
112.     public void testStart_failed() throws Exception {
113.       final Exception exception = new Exception("deliberate");
114.       AbstractIdleService service =
115.           new DefaultService() {
116.             @Override
117.             protected void startUp() throws Exception {
118.               throw exception;
119.             }
120.           };
121.       try {
122.         service.startAsync().awaitRunning();
123.         fail();
124.       } catch (RuntimeException e) {
125.         assertThat(e).hasCauseThat().isSameInstanceAs(exception);
126.       }
127.       assertEquals(Service.State.FAILED, service.state());
128.     }
129. 
130.     public void testStop_failed() throws Exception {
131.       final Exception exception = new Exception("deliberate");
132.       AbstractIdleService service =
133.           new DefaultService() {
134.             @Override
135.             protected void shutDown() throws Exception {
136.               throw exception;
137.             }
138.           };
139.       service.startAsync().awaitRunning();
140.       try {
141.         service.stopAsync().awaitTerminated();
142.         fail();
143.       } catch (RuntimeException e) {
144.         assertThat(e).hasCauseThat().isSameInstanceAs(exception);
145.       }
146.       assertEquals(Service.State.FAILED, service.state());
147.     }
148.   }
149. 
150.   public void testStart() {
151.     TestService service = new TestService();
152.     assertEquals(0, service.startUpCalled);
153.     service.startAsync().awaitRunning();
154.     assertEquals(1, service.startUpCalled);
155.     assertEquals(Service.State.RUNNING, service.state());
156.     assertThat(service.transitionStates).containsExactly(Service.State.STARTING);
157.   }
