231.   public void testServiceToString() {
232.     AbstractIdleService service = new TestService();
233.     assertEquals("TestService [NEW]", service.toString());
234.     service.startAsync().awaitRunning();
235.     assertEquals("TestService [RUNNING]", service.toString());
236.     service.stopAsync().awaitTerminated();
237.     assertEquals("TestService [TERMINATED]", service.toString());
238.   }
239. 
240.   public void testTimeout() throws Exception {
241.     // Create a service whose executor will never run its commands
242.     Service service =
243.         new TestService() {
244.           @Override
245.           protected Executor executor() {
246.             return new Executor() {
247.               @Override
248.               public void execute(Runnable command) {}
249.             };
250.           }
251. 
252.           @Override
253.           protected String serviceName() {
254.             return "Foo";
255.           }
256.         };
257.     try {
258.       service.startAsync().awaitRunning(1, TimeUnit.MILLISECONDS);
259.       fail("Expected timeout");
260.     } catch (TimeoutException e) {
261.       assertThat(e)
262.           .hasMessageThat()
263.           .isEqualTo("Timed out waiting for Foo [STARTING] to reach the RUNNING state.");
264.     }
265.   }
266. 
267.   private static class TestService extends AbstractIdleService {
268.     int startUpCalled = 0;
269.     int shutDownCalled = 0;
270.     final List<State> transitionStates = Lists.newArrayList();
271. 
272.     @Override
273.     protected void startUp() throws Exception {
274.       assertEquals(0, startUpCalled);
275.       assertEquals(0, shutDownCalled);
276.       startUpCalled++;
277.       assertEquals(State.STARTING, state());
278.     }
279. 
280.     @Override
281.     protected void shutDown() throws Exception {
282.       assertEquals(1, startUpCalled);
283.       assertEquals(0, shutDownCalled);
284.       shutDownCalled++;
285.       assertEquals(State.STOPPING, state());
286.     }
287. 
288.     @Override
289.     protected Executor executor() {
290.       transitionStates.add(state());
291.       return directExecutor();
292.     }
293.   }
294. }
